18	    ///   beforeEach(() => {
19	    ///     // some setup
20	    ///   });
21	    ///   beforeEach(() => {
22	    ///     // some setup
23	    ///   });
24	    ///   test('foo_test', () => {
25	    ///    // some test
26	    ///   });
27	    /// });
28	    /// ```
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// describe('foo', () => {
32	    ///   beforeEach(() => {
33	    ///     // some setup
34	    ///   });
35	    ///   test('foo_test', () => {
36	    ///     afterAll(() => {
37	    ///       // some teardown
38	    ///     });
39	    ///    afterAll(() => {
40	    ///      // some teardown
41	    ///    });
42	    ///   });
43	    /// });
44	    /// ```
