78	impl HooksContext {
79	    fn add(&mut self, hook_name: &str) -> u8 {
80	        let counter = match hook_name {
81	            "after" => &mut self.after,
82	            "afterAll" => &mut self.after_all,
83	            "afterEach" => &mut self.after_each,
84	            "before" => &mut self.before,
85	            "beforeEach" => &mut self.before_each,
86	            "beforeAll" => &mut self.before_all,
87	            _ => return 0, // Should never happen
88	        };
89	        if *counter <= 1 {
90	            *counter += 1;
91	        }
92	
93	        *counter
94	    }
95	}
